const imageData = "";
const portraitData = "";
const goldData = "";
const heroData = "";
const coinData = "";
const pgLogoData = "";
const priceGoldData = "";
const html = page
  .replaceAll("__PGLOGO__", `data:image/png;base64,${pgLogoData}`)
  .replaceAll("__PRICE_GOLD__", `data:image/jpeg;base64,${priceGoldData}`)
  .replaceAll("__HERO__", `data:image/png;base64,${heroData}`)
  .replaceAll("__COIN__", `data:image/png;base64,${coinData}`)
  .replaceAll("__BANNER__", `data:image/jpeg;base64,${imageData}`)
  .replaceAll("__PORTRAIT__", `data:image/jpeg;base64,${portraitData}`)
  .replaceAll("__GOLD__", `data:image/jpeg;base64,${goldData}`);

function parseTable(source, heading) {
  const title = source.indexOf(heading);
  if (title < 0) return [];
  const start = source.indexOf('<table', title);
  const tableEnd = source.indexOf('</table>', start);
  if (start < 0 || tableEnd < 0) return [];
  const table = source.slice(start, tableEnd + 8);
  const rows = [...table.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].slice(1);
  return rows.map(m => {
    const cells = [...m[1].matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi)].map(c => c[1].replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim());
    return { purity: cells[0], price: Number((cells[1] || '').match(/[0-9]+(?:\.[0-9]+)?/)?.[0]) };
  }).filter(r => (r.purity === '999' || r.purity === '916') && Number.isFinite(r.price));
}
function liveTimestamp(source) {
  const all = [...source.matchAll(/Last Update\s+(\d{1,2}-[A-Za-z]{3}-\d{4}\s+\d{2}:\d{2}:\d{2})/g)].map(m => m[1]).filter(v => !v.includes('2021'));
  return all[0] || null;
}
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/api/prices') {
      try {
        const upstream = await fetch(`https://publicgold.com.my/?_=${Date.now()}`, { headers: { 'User-Agent': 'Mozilla/5.0 (compatible; GoldPriceReader/1.0)', 'Accept': 'text/html' }, cf: { cacheTtl: 0, cacheEverything: false } });
        if (!upstream.ok) throw new Error(`Official rate page returned ${upstream.status}.`);
        const source = await upstream.text();
        const jewel = parseTable(source, 'PG Jewel');
        const buyback = parseTable(source, 'Non-PG Gold Buyback');
        const updatedAt = liveTimestamp(source);
        if (jewel.length !== 2 || buyback.length !== 2 || !updatedAt) throw new Error('Could not verify both price tables and their update time.');
        return Response.json({ ok: true, jewel, buyback, updatedAt, source: 'https://publicgold.com.my/' }, { headers: { 'cache-control': 'no-store, max-age=0' } });
      } catch (error) {
        return Response.json({ ok: false, error: 'Harga semasa Public Gold tidak dapat dipaparkan buat sementara waktu.' }, { status: 503, headers: { 'cache-control': 'no-store, max-age=0' } });
      }
    }
    if (url.pathname !== '/') return new Response('Not found', { status: 404 });
    return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'public, max-age=300' } });
  },
};
